<template>
  <AppLoader v-if="isLoading && !accountInfo" subject="profile information" />
  <template v-else>
    <AppError v-if="error" :error="error" title="Failed to load profile information" />
    <section v-else class="flex flex-col gap-10">
      <PageTitle title="My Account" show-doc>
        <FilterTabsNav v-if="isCanvasserOrSubCanvasser && !isEditPage" :items="navigationItems" rounded />
      </PageTitle>
      <GoBackButton v-if="isCanvasserEditPage" subject="account" :fallback-to="{ name: 'account-canvasser' }" />
      <GoBackButton v-else-if="isEditPage" subject="account" :fallback-to="{ name: 'account' }" />
      <AppEmpty v-if="!accountInfo" subject="account information" />
      <NuxtPage v-else :account-info="accountInfo" />
    </section>
  </template>
</template>

<script setup lang="ts">
import type { NavigationItem } from '~/types/projects';

const route = useRoute();
const { isCanvasserOrSubCanvasser, isSubcontractorCanvasser } = useUserRole();
const { accountInfo, isLoading, error } = useAccount();

const isEditPage = computed(() => route.path.includes('/edit/') || route.path.includes('/create/'));
const isCanvasserEditPage = computed(() => route.path.includes('/canvasser/edit/'));

const navigationItems = computed<NavigationItem[]>(() => [
  {
    label: 'General',
    to: { name: 'account' },
    selected: route.name === 'account',
  },
  ...(isSubcontractorCanvasser.value
    ? []
    : [
        {
          label: 'Referral Program',
          to: { name: 'account-referral-program' },
          selected: route.name === 'account-referral-program',
        } satisfies NavigationItem,
      ]),
  {
    label: 'Canvasser Application',
    to: { name: 'account-canvasser' },
    selected: route.name === 'account-canvasser',
  },
]);

useHead({
  title: 'My Account',
});
</script>
