import { getAccountDetails } from '~/client';

export const useAccount = defineQuery(() => {
  const {
    data: accountInfo,
    error,
    isLoading,
  } = useQuery({
    key: ['account'],
    query: () => getAccountDetails({ composable: '$fetch' }),
    staleTime: 0,
  });

  return {
    accountInfo,
    error,
    isLoading,
  };
});
